import Foundation

/// Action proposals generated by AI catch-up planning to recover a delayed schedule.
public enum CatchupAdjustmentProposal: Equatable, Sendable {
    case move(itemId: String, newTime: Date)
    case merge(itemId: String, targetItemId: String)
    case skip(itemId: String)
}

/// Pure deterministic validator ensuring AI catch-up proposals adhere to safety constraints.
public struct CatchupAdjustmentValidator {

    public static func validate(
        proposal: CatchupAdjustmentProposal,
        existingEvents: [ScheduledEvent],
        settings: PlanSettings,
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> ValidationResult {
        var reasons: [String] = []

        switch proposal {
        case .move(let itemId, let newTime):
            // 1. Cannot move into the past
            if newTime < now {
                reasons.append("Cannot move meal '\(itemId)' to past time (\(newTime)) relative to now (\(now))")
            }

            // 2. Cannot violate minimum meal gap with other meals
            let minGapMinutes = Double(settings.minMealGapMinutes)
            for other in existingEvents where other.itemId != itemId && other.item.type == .meal {
                let gapMinutes = abs(newTime.timeIntervalSince(other.resolvedTime)) / 60.0
                if gapMinutes < minGapMinutes {
                    reasons.append("Moving '\(itemId)' to \(newTime) violates minimum meal gap (\(Int(gapMinutes))m < \(Int(minGapMinutes))m) with '\(other.itemId)'")
                }
            }

            // 3. Cannot move into quiet hours
            if isQuietHours(date: newTime, settings: settings, calendar: calendar) {
                reasons.append("Cannot move meal '\(itemId)' into sleep quiet hours")
            }

        case .merge(let itemId, let targetItemId):
            if itemId == targetItemId {
                reasons.append("Cannot merge meal '\(itemId)' into itself")
            }

        case .skip:
            break
        }

        if !reasons.isEmpty {
            return .invalid(reasons: reasons)
        }

        return .valid
    }

    private static func isQuietHours(date: Date, settings: PlanSettings, calendar: Calendar) -> Bool {
        let wakeParts = parseTime(settings.wake)
        let bedParts = parseTime(settings.bed)

        let comps = calendar.dateComponents([.hour, .minute], from: date)
        guard let hour = comps.hour, let minute = comps.minute else { return false }
        let currentMinutes = hour * 60 + minute

        let wakeMinutes = wakeParts.hour * 60 + wakeParts.minute
        let bedMinutes = bedParts.hour * 60 + bedParts.minute

        if bedMinutes > wakeMinutes {
            return currentMinutes >= bedMinutes || currentMinutes < wakeMinutes
        } else {
            return currentMinutes >= bedMinutes && currentMinutes < wakeMinutes
        }
    }

    private static func parseTime(_ timeString: String) -> (hour: Int, minute: Int) {
        let parts = timeString.split(separator: ":").compactMap { Int($0) }
        guard parts.count == 2 else { return (0, 0) }
        return (parts[0], parts[1])
    }
}
